                                                                                                                                                                                                              
  CREATE TABLE "TENANT_PROJECT_REPORT_POLICY"                                                                                                                                                      
   (	"REPORT_POLICY_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                   
	"CREATION_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                        
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                   
	"UPDATE_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                          
	"REMARK" NVARCHAR2(512),                                                                                                                                                                                     
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                          
	"PROJECT_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                   
	"MINUTES" NUMBER NOT NULL ENABLE,                                                                                                                                                                            
	"TIMES" NUMBER NOT NULL ENABLE,                                                                                                                                                                              
	"IS_ENABLE" NUMBER DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                                
	"TIME_TYPE" VARCHAR2(32) DEFAULT 'MINUTES',                                                                                                                                                                  
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                
	 PRIMARY KEY ("REPORT_POLICY_ID")                                                                                                                                                                            
  USING INDEX  ENABLE,                                                                                                                                                                                        
	 CHECK (time_type in ('HOUR', 'MINUTES')) ENABLE                                                                                                                                                             
   ) ;                                                                                                                                                                                                        

